create table if not exists departments(id uuid primary key default gen_random_uuid(),hospital_id uuid not null references hospitals(id) on delete cascade,name text not null,head text,phone text,created_at timestamptz not null default now(),unique(hospital_id,name));
create table if not exists import_runs(id uuid primary key default gen_random_uuid(),hospital_id uuid not null references hospitals(id) on delete cascade,kind text not null,file_sha256 text not null,file_name text,rows int not null,created int not null default 0,updated int not null default 0,skipped int not null default 0,errors int not null default 0,dry_run boolean not null,user_id uuid references users(id) on delete set null,created_at timestamptz not null default now());
create index if not exists idx_import_runs on import_runs(hospital_id,created_at desc);
